{"hypotheses": [
  {
    "name": "Cautious Capital Allocators",
    "mechanism": "Firms with low asset growth (AssetGrowth) and high cash productivity (CashProd), but low net equity issuance (NetEquityFinance) demonstrate disciplined capital allocation and superior operational efficiency. Combining these signals identifies companies that grow cautiously, generate cash flow, and avoid dilutive financing, capturing a persistent premium not fully harvested by each primitive alone.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": 1.0, "primitive": "CashProd"},
        {"weight": -0.5, "primitive": "NetEquityFinance"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Skeptical Analyst Contrarian",
    "mechanism": "Stocks with negative recent analyst forecast revisions (AnalystRevision) that experience positive earnings surprises (EarningsSurprise), but have low institutional ownership among highly shorted stocks (IO_ShortInterest), reflect overly pessimistic analyst sentiment and crowded shorting. The combination exploits post-surprise reversals and forced covering not captured by each signal alone.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AnalystRevision"},
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": -0.5, "primitive": "IO_ShortInterest"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "EarningsSurprise", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Momentum Quality Overlay",
    "mechanism": "Stocks with strong 6-month momentum (Mom6m), but only among those with high Piotroski F-score (PS) and low market leverage (Leverage), should outperform because quality filters mitigate momentum crashes and select for robust balance sheets, delivering a more resilient premium than momentum or quality alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom6m"},
        {"weight": 0.5, "primitive": "PS"},
        {"weight": -0.5, "primitive": "Leverage"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "R&D Asset Efficiency",
    "mechanism": "Firms with high R&D over market cap (RD) and high gross profits to total assets (GP), but low capital investment growth (grcapx), reflect efficient utilization of intangible investments. This triple-screen captures companies that innovate productively without over-investing in physical assets, leading to a unique premium.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": 1.0, "primitive": "GP"},
        {"weight": -1.0, "primitive": "grcapx"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "GP", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Reversal Under Uncertainty",
    "mechanism": "Short-term reversals (STreversal) are more pronounced when combined with high forecast dispersion (ForecastDispersion) and high realized volatility (RealizedVol), as uncertainty and disagreement amplify mean-reverting flows and market overreactions, generating a premium unexploited by each component in isolation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "STreversal"},
        {"weight": 0.5, "primitive": "ForecastDispersion"},
        {"weight": 0.5, "primitive": "RealizedVol"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "STreversal", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.5,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Value with Operating Momentum",
    "mechanism": "Combining high book-to-market (BM), improvements in operating profitability (OperProf), and strong revenue surprise (RevenueSurprise) targets value stocks with positive business momentum, capturing a premium driven by the market’s underreaction to improving fundamentals in cheap stocks.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 0.5, "primitive": "OperProf"},
        {"weight": 0.5, "primitive": "RevenueSurprise"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Profitability with Conservative Investment",
    "mechanism": "Firms with high operating profitability (OperProfRD) and low asset growth (AssetGrowth), further filtered by low share issuance (ShareIss1Y), combine persistent profitability with disciplined capital expansion, capturing a premium driven by management prudence and efficient capital allocation, beyond the sum of the parts.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProfRD"},
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": -0.5, "primitive": "ShareIss1Y"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Low Attention Winners",
    "mechanism": "Stocks with strong trailing returns (Mom12m) that are not widely followed (ChNAnalyst) and exhibit low bid-ask spreads (BidAskSpread) benefit from underreaction and efficient trading, capturing a premium where price drift persists in overlooked but liquid stocks—an edge beyond momentum or illiquidity effects alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "ChNAnalyst"},
        {"weight": -0.5, "primitive": "BidAskSpread"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 30
  }
]}
